// Assuming the incoming data is in `items[0].json.issues` array
const issues = $input.first().json.issues;

// Create a map to store ticket information
const ticketMap = {};

// First pass: Extract basic ticket information
for (const issue of issues) {
  const key = issue.key;
  const fields = issue.fields;

  // Extract priority name safely
  const priority = fields.priority ? fields.priority.name : "N/A";

  // Extract story points - customfield_11901 might be the story points field
  const storyPoint = fields.customfield_11901 ? 
                     String(fields.customfield_11901) : "0";

  // Initialize ticket object
  ticketMap[key] = {
    ticketId: key,
    priority: priority,
    storyPoint: storyPoint,
    blocksBy: []
  };
}

// Second pass: Process blocking relationships from issuelinks
for (const issue of issues) {
  const key = issue.key;
  const fields = issue.fields;

  // Get issue links if they exist
  const links = fields.issuelinks || [];

  for (const link of links) {
    // Check if this is a "Blocks" relationship
    // Looking at your example, you want links where this ticket is blocked by another
    if (link.type && link.type.name === "Blocks") {
      // Check inwardIssue (this ticket is blocked by inwardIssue)
      if (link.inwardIssue) {
        const blockerKey = link.inwardIssue.key;
        // Make sure the blocking ticket exists in our map
        if (ticketMap[blockerKey]) {
          // Add the blocker to this ticket's blocksBy array
          ticketMap[key].blocksBy.push({
            ticket: blockerKey,
            priority: ticketMap[blockerKey].priority,
            storyPoint: ticketMap[blockerKey].storyPoint
          });
        }
      }

      // Also check outwardIssue (this ticket blocks outwardIssue)
      if (link.outwardIssue) {
        const blockedKey = link.outwardIssue.key;
        // If this ticket blocks another, the other ticket should have this in blocksBy
        if (ticketMap[blockedKey]) {
          // The blocked ticket is blocked by this ticket
          ticketMap[blockedKey].blocksBy.push({
            ticket: key,
            priority: ticketMap[key].priority,
            storyPoint: ticketMap[key].storyPoint
          });
        }
      }
    }
  }
}

// Convert to array format
const ticketsArray = Object.values(ticketMap);

// Create the final output structure
const output = {
  tickets: ticketsArray
};

// Return in n8n format
return [{ json: output }];

