const items = [];

for (const item of $input.all()) {
  const text = item.json.output || item.json.text || JSON.stringify(item.json);

  // Match JSON starting with {"issueUpdates":[ ... ]}
  const regex = /{\s*"issueUpdates"\s*:\s*\[[\s\S]*?\]\s*}/;
  const match = text.match(regex);

  if (match) {
    let jsonString = match[0];

    try {
      // Try to parse directly
      const parsed = JSON.parse(jsonString);

      // Reformat JSON properly
      const formatted = JSON.stringify(parsed, null, 2);

      items.push({
        json: {
          result: formatted
        }
      });
    } catch (e) {
      // If parsing fails, try to fix minor issues
      let fixed = jsonString
        .replace(/,\s*([}\]])/g, "$1") // remove trailing commas
        .replace(/[\r\n\t]/g, " ")      // normalize whitespace
        .replace(/\s+/g, " ");

      try {
        const parsed = JSON.parse(fixed);
        const formatted = JSON.stringify(parsed, null, 2);
        items.push({
          json: {
            result: formatted,
            note: "Fixed minor JSON issues automatically"
          }
        });
      } catch (e2) {
        // If still invalid, return raw text
        items.push({
          json: {
            error: "Failed to parse JSON properly",
            raw: jsonString
          }
        });
      }
    }
  } else {
    items.push({
      json: {
        error: "No JSON block starting with 'issueUpdates' found"
      }
    });
  }
}

return items;

